def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict = {k: v for k, v in chain_dict.items() if v}

    result = []
    current = chain_dict['cgj']

    while current:
        result.append(current)
        next_item = chain_dict.get(current, None)
        if next_item is None:
            break
        current = next_item

    return ','.join(result)
